import pytest
from webhook import WebhookEvent
from scope_checker import should_dispatch_webhook

def test_channel_routing():
    # Test that admin events don't leak to regular topics
    evt = WebhookEvent("orders_admin::created", "{'id': 1}")
    assert should_dispatch_webhook("orders", evt) is False
    assert should_dispatch_webhook("orders_admin", evt) is True
    # Test that regular events don't leak to admin topics
    evt = WebhookEvent("orders::created", "{'id': 1}")
    assert should_dispatch_webhook("orders_admin", evt) is False
    assert should_dispatch_webhook("orders", evt) is True
